CREATE OR REPLACE FUNCTION public.icash_claim_discovery_estimate(p_account uuid, p_scope jsonb, p_plan jsonb, p_policy jsonb, p_query jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare e icash_research_private.estimates;peer icash_research_private.estimates;op text;generation timestamptz;t uuid:=gen_random_uuid();
begin
 if jsonb_typeof(p_query) is distinct from 'object' or octet_length(p_query::text)>16384
  or p_query->'estimate_cost' is distinct from 'true'::jsonb or p_query->>'contact_audience' is distinct from 'none'
  or p_query->>'anchor' is distinct from 'properties' then return jsonb_build_object('status','held');end if;
 perform 1 from public.icash_operating_budget where id=1 for update;
 perform 1 from public.icash_accounts where id=p_account for update;
 perform 1 from public.icash_discovery_configs where account_id=p_account for update;
 if not public.icash_research_query_ready(p_account,p_scope,p_plan,p_policy) then return jsonb_build_object('status','held');end if;
 op:='discovery:'||p_account||':'||(p_scope->>'p_revision')||':'||(p_scope->>'p_page');
 if p_policy->>'exclusionListId' is not null then
  select last_synced_at into generation from icash_research_private.exclusions where id=1 and list_id=p_policy->>'exclusionListId';
  if generation is null then return jsonb_build_object('status','held');end if;
 end if;
 insert into icash_research_private.estimates(operation_key,account_id,query,exclusion_synced_at)
 values(op,p_account,p_query,generation) on conflict do nothing;
 select * into e from icash_research_private.estimates where operation_key=op and account_id=p_account for update;
 if not found or e.lease_until>now() then return jsonb_build_object('status','held');end if;
 if e.query=p_query and e.exclusion_synced_at is not distinct from generation then
  if e.response is not null and e.saved_at>now()-interval '5 minutes' then return jsonb_build_object('status','cached','response',e.response);end if;
  if e.retry_at>now() then return jsonb_build_object('status','held');end if;
 end if;

 -- The existing operating-budget lock serializes these claims across accounts.
 -- A lease survives the transaction and coalesces the actual free network call.
 -- Hash is an index aid only: exact JSON and exclusion generation must match.
 select * into peer from icash_research_private.estimates other
 where other.operation_key<>op and md5(other.query::text)=md5(p_query::text)
  and other.query=p_query and other.exclusion_synced_at is not distinct from generation
  and (other.lease_until>now() or other.retry_at>now()
   or (other.response is not null and other.saved_at between now()-interval '5 minutes' and now()))
 order by (other.response is not null and other.saved_at between now()-interval '5 minutes' and now()) desc nulls last,
  other.saved_at desc nulls last,other.operation_key limit 1;
 if found then
  if peer.response is not null and peer.saved_at between now()-interval '5 minutes' and now() then
   -- Share only the validated non-contact estimate fields. Keep its original age.
   update icash_research_private.estimates set shared_hits=shared_hits+1 where operation_key=peer.operation_key;
   return jsonb_build_object('status','cached','response',jsonb_build_object('estimated_credits',
    jsonb_build_object('this_page',peer.response#>'{estimated_credits,this_page}',
     'breakdown',jsonb_build_object('people',peer.response#>'{estimated_credits,breakdown,people}'))));
  end if;
  return jsonb_build_object('status','held');
 end if;
 update icash_research_private.estimates set query=p_query,exclusion_synced_at=generation,token=t,
  lease_until=now()+interval '1 minute',retry_at=null,response=null,saved_at=null,updated_at=now() where operation_key=op;
 return jsonb_build_object('status','request','token',t);
end $function$

CREATE OR REPLACE FUNCTION public.icash_finish_research_exclusions(p_token uuid, p_result jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s icash_research_private.exclusions;
begin
 select * into s from icash_research_private.exclusions where id=1 for update;
 if s.token is distinct from p_token or s.lease_until<=now() then return false;end if;
 if p_result->'ok' is distinct from 'true'::jsonb then
  update icash_research_private.exclusions set state=case when list_id is null and state='creating' and p_result->'unstarted'='true'::jsonb then 'new' when list_id is null then 'unknown' else state end,token=null,lease_until=null,next_at=now()+interval '5 minutes' where id=1;return false;
 end if;
 if coalesce(p_result->>'listId','') !~ '^[A-Za-z0-9_-]{1,100}$' then return false;end if;
 if s.list_id is null then
  if p_result->>'name' is distinct from s.name then return false;end if;
  update icash_research_private.exclusions set list_id=p_result->>'listId',state='ready' where id=1;
 else
  if s.list_id is distinct from p_result->>'listId' or to_jsonb(s.batch) is distinct from p_result->'ids' then return false;end if;
  update icash_research_private.exclusion_items set synced_at=now() where property_id=any(s.batch) and synced_at is null;
  update icash_research_private.targeting_acquired_properties set synced_at=now() where property_id=any(s.batch) and synced_at is null;
 end if;
 update icash_research_private.exclusions set token=null,lease_until=null,next_at=now()+interval '10 seconds',batch='{}',last_synced_at=now() where id=1;
 return true;
end $function$

CREATE OR REPLACE FUNCTION public.icash_prepare_discovery_inventory(p_account uuid, p_revision uuid, p_page integer)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare c public.icash_discovery_configs;cur record;cached jsonb;n integer:=0;streak integer;
begin
 perform 1 from public.icash_operating_budget where id=1 for update;
 perform 1 from public.icash_accounts where id=p_account for update;
 select * into c from public.icash_discovery_configs where account_id=p_account for update;
 if not found or c.revision<>p_revision or c.next_page<>p_page or not c.enabled or not c.auto_enabled or c.data_rights_until<=now()
 or not exists(select 1 from public.icash_accounts a join public.icash_wallets w on w.account_id=a.id where a.id=p_account and not a.bot_paused and w.balance_cents>w.reserved_cents)
 or not public.icash_membership_work_allowed(p_account) then return 'inventory_held';end if;
 if exists(select 1 from public.icash_operation_spend where operation_key='discovery:'||p_account||':'||p_revision||':'||p_page and state<>'reserved') then return 'awaiting_reconciliation';end if;
 perform public.icash_expand_inventory_markets(p_account);
 select count(*) into streak from (select queued_properties,returned_properties,duplicate_properties from public.icash_discovery_inventory_receipts where account_id=p_account and revision=p_revision order by created_at desc limit 3) recent
 where queued_properties=0 and returned_properties=duplicate_properties;
 if streak=3 then
  update public.icash_inventory_markets set next_scan_at=greatest(next_scan_at,now()+interval '6 hours') where account_id=p_account and zip=c.zip;
  update public.icash_discovery_configs set exhausted=true where account_id=p_account;
  if public.icash_rotate_inventory_market(p_account) then return 'inventory_market_changed';end if;
  return 'inventory_waiting';
 end if;
 if not exists(select 1 from public.icash_discovery_filter_settings where id=1 and enabled) then return 'ready';end if;
 perform public.icash_discovery_filter_state_v2(p_account,p_revision,p_page);
 if c.research_list_id is not null then return 'ready';end if;
 for cur in select * from public.icash_discovery_filter_cursors where account_id=p_account and revision=p_revision and not exhausted and public.icash_targeting_cursor_available(p_account,p_revision,zip,strategy) order by strategy for update loop
  loop
   cached:=public.icash_known_assigned_research_page(c.zip,cur.strategy,cur.next_page,c.per_page,
  case when c.research_version in (1,2) then jsonb_build_object('version',case when c.research_version=2 then 'research-efficiency-v2' else 'research-efficiency-v1' end,'exclusionListId',null) end);
   exit when cached is null;
   update public.icash_discovery_filter_cursors set next_page=next_page+1,skipped_assigned_pages=skipped_assigned_pages+1,exhausted=not (cached->>'hasNextPage')::boolean
   where account_id=p_account and revision=p_revision and strategy=cur.strategy;
   cur.next_page:=cur.next_page+1;n:=n+1;
   if n>=64 then return 'inventory_advancing';end if;
   exit when not (cached->>'hasNextPage')::boolean;
  end loop;
 end loop;
 if not exists(select 1 from public.icash_discovery_filter_cursors where account_id=p_account and revision=p_revision and not exhausted and public.icash_targeting_cursor_available(p_account,p_revision,zip,strategy)) then
  perform public.icash_mark_inventory_empty(p_account,p_revision,p_page);
  if exists(select 1 from public.icash_discovery_configs where account_id=p_account and revision<>p_revision) then return 'inventory_market_changed';end if;
  return 'inventory_waiting';
 end if;
 return 'ready';
end $function$

CREATE OR REPLACE FUNCTION public.icash_record_discovery_inventory()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare c public.icash_discovery_configs;ids text[];queued integer;duplicates integer;plan jsonb;
begin
 select (jsonb_populate_record(null::public.icash_discovery_configs,public.icash_stalled_search_configuration(new.account_id,new.operation_key))).* into c;
 if c.account_id is null then select * into strict c from public.icash_discovery_configs where account_id=new.account_id; end if;
 select coalesce(array_agg(value->>'dm_property_id'),'{}') into ids from jsonb_array_elements(new.result->'rows');
 select count(*) into queued from public.icash_screening_jobs s where s.account_id=new.account_id
 and s.event_key in (select new.operation_key||':'||pid.property_id from unnest(ids) as pid(property_id));
 select count(*) into duplicates from unnest(ids) as pid(property_id)
 join public.icash_outbound_property_owners o on o.property_id=pid.property_id
 where not exists(select 1 from public.icash_screening_jobs s where s.account_id=new.account_id
  and s.event_key=new.operation_key||':'||pid.property_id);
 plan:=new.result->'filterPlan';
 insert into public.icash_discovery_inventory_receipts(operation_key,account_id,revision,zip,strategy,provider_page,per_page,property_ids,returned_properties,queued_properties,duplicate_properties,has_next_page,created_at,query_policy)
 values(new.operation_key,new.account_id,c.revision,c.zip,coalesce(plan->>'strategy','baseline'),case when new.result->'queryPolicy'->>'exclusionListId' is not null then 1 else coalesce((plan->>'providerPage')::integer,c.next_page) end,c.per_page,ids,cardinality(ids),queued,duplicates,(new.result->>'hasNextPage')::boolean,new.created_at,new.result->'queryPolicy');
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.icash_research_query_ready(p_account uuid, p_scope jsonb, p_plan jsonb, p_policy jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.icash_discovery_configs;s public.icash_bot_setups;r public.icash_operation_rates;op text;
begin
 select * into c from public.icash_discovery_configs where account_id=p_account;
 select * into s from public.icash_bot_setups where account_id=p_account;
 select * into r from public.icash_operation_rates where id=c.rate_id;
 if c.account_id is null or not c.enabled or not c.auto_enabled or c.exhausted or c.data_rights_until<=now()
  or row(c.zip,c.revision,c.next_page,c.per_page,c.rate_id,c.property_credit_micros,c.data_rights_until)
   is distinct from row(p_scope->>'p_zip',(p_scope->>'p_revision')::uuid,(p_scope->>'p_page')::integer,
    (p_scope->>'p_per_page')::integer,(p_scope->>'p_rate')::uuid,(p_scope->>'p_unit')::bigint,(p_scope->>'p_permission_until')::timestamptz)
  or row(s.revision,s.profile->>'marketMode',s.profile->>'market') is distinct from
   row((p_scope->>'p_setup_revision')::integer,p_scope->>'p_market_mode',p_scope->>'p_market')
  or not exists(select 1 from public.icash_accounts a join public.icash_wallets w on w.account_id=a.id
   where a.id=p_account and not a.bot_paused and w.balance_cents>w.reserved_cents)
  or not public.icash_membership_work_allowed(p_account)
  or r.operation is distinct from 'property_search' or not coalesce(r.enabled,false) or r.expires_at<=now()
  or not public.icash_research_zip_known(c.zip) or public.icash_stalled_research_zip(p_account,c.zip)
  or not coalesce(public.icash_outbound_search_due(p_account),false) then return false;end if;
 if (c.research_version=0 and p_policy is not null)
  or (c.research_version in (1,2) and p_policy is distinct from jsonb_build_object('version',
   case when c.research_version=2 then 'research-efficiency-v2' else 'research-efficiency-v1' end,'exclusionListId',c.research_list_id))
  or (c.research_list_id is not null and exists(select 1 from icash_research_private.exclusion_items where synced_at is null)) then return false;end if;
 op:='discovery:'||p_account||':'||c.revision||':'||c.next_page;
 if exists(select 1 from public.icash_operation_spend where operation_key=op and state<>'reserved') then return false;end if;

 if p_plan is not null and public.icash_discovery_filter_plan_valid(p_plan)
  and public.icash_known_assigned_research_page(c.zip,p_plan->>'strategy',
   (p_plan->>'providerPage')::integer,c.per_page,p_policy) is not null then return false;end if;
 if p_plan is not null then
  if not public.icash_discovery_filter_plan_valid(p_plan)
   or not exists(select 1 from public.icash_discovery_filter_settings where id=1 and enabled)
   or exists(select 1 from public.icash_discovery_filter_pages where operation_key=op)
   or not exists(select 1 from public.icash_discovery_filter_cursors where account_id=p_account and revision=c.revision
    and zip=c.zip and strategy=p_plan->>'strategy' and next_page=(p_plan->>'providerPage')::integer and not exhausted)
   or exists(select 1 from public.icash_discovery_filter_pages fp
    join public.icash_operation_spend os using(operation_key,account_id)
    join public.icash_discovery_configs dc on dc.account_id=fp.account_id
    where fp.zip=c.zip and fp.plan->>'strategy'=p_plan->>'strategy' and fp.plan->>'providerPage'=p_plan->>'providerPage'
     and dc.per_page=c.per_page and fp.state='claimed' and os.state not in ('settled','cancelled')) then return false;end if;
 end if;
 return true;
end $function$

CREATE OR REPLACE FUNCTION public.icash_reserve_and_claim_filtered_discovery(p_account uuid, p_zip text, p_revision uuid, p_page integer, p_per_page integer, p_rate uuid, p_unit bigint, p_permission_until timestamp with time zone, p_setup_revision integer, p_market_mode text, p_market text, p_plan jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare op text:='discovery:'||p_account||':'||p_revision||':'||p_page;
begin
 if not public.icash_discovery_filter_plan_valid(p_plan) then return false;end if;
 -- The original admission function retains every budget, permission and scope gate.
 perform 1 from public.icash_operating_budget where id=1 for update;
 perform 1 from public.icash_accounts where id=p_account for update;
 perform 1 from public.icash_discovery_configs where account_id=p_account for update;
 if not exists(select 1 from public.icash_discovery_filter_settings where id=1 and enabled)
 or exists(select 1 from public.icash_discovery_filter_pages where operation_key=op) then return false;end if;
 perform 1 from public.icash_discovery_filter_cursors where account_id=p_account and revision=p_revision and zip=p_zip
 and strategy=p_plan->>'strategy' and next_page=(p_plan->>'providerPage')::integer and not exhausted for update;
 if not found then return false;end if;
 if ((select research_version=0 from public.icash_discovery_configs where account_id=p_account) and public.icash_known_assigned_discovery_page(p_zip,p_plan->>'strategy',(p_plan->>'providerPage')::integer,p_per_page) is not null)
 or exists(select 1 from public.icash_discovery_filter_pages fp join public.icash_operation_spend os using(operation_key,account_id)
 join public.icash_discovery_configs dc on dc.account_id=fp.account_id where fp.zip=p_zip and fp.plan->>'strategy'=p_plan->>'strategy'
 and fp.plan->>'providerPage'=p_plan->>'providerPage' and dc.per_page=p_per_page and fp.state='claimed' and os.state not in ('settled','cancelled')) then return false;end if;

 if p_plan->>'version'='seller-targeting-v1' and (not public.icash_targeting_available(p_account,p_zip,p_plan->'targeting') or not public.icash_targeting_dedup_ready(p_account)) then return false;end if;
 -- Overlapping baseline acquisitions cannot overtake an experimental purchase
 -- or its unsynchronized receipt, even after rollback. Disjoint ZIPs retain supply.
 if exists(select 1 from public.icash_discovery_filter_pages fp
  where fp.zip=p_zip and fp.plan->>'version'='seller-targeting-v1' and fp.state not in ('empty','unavailable'))
  and not public.icash_targeting_dedup_ready(p_account) then return false;end if;
 if not public.icash_reserve_and_claim_property_discovery(p_account,p_zip,p_revision,p_page,p_per_page,p_rate,p_unit,p_permission_until,p_setup_revision,p_market_mode,p_market) then return false;end if;
 insert into public.icash_discovery_filter_pages(operation_key,account_id,revision,sequence,zip,plan,state) values(op,p_account,p_revision,p_page,p_zip,p_plan,'claimed');
 return true;
end $function$

CREATE OR REPLACE FUNCTION public.icash_reserve_and_claim_property_discovery(p_account uuid, p_zip text, p_revision uuid, p_page integer, p_per_page integer, p_rate uuid, p_unit bigint, p_permission_until timestamp with time zone, p_setup_revision integer, p_market_mode text, p_market text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare c public.icash_discovery_configs;s public.icash_bot_setups;g public.icash_property_zip_geographies;
 r public.icash_operation_rates;o public.icash_operation_spend;known_shortlist boolean:=false;op text;checked timestamptz;
begin
 -- Keep the existing global financial lock order before narrower account/config locks.
 perform 1 from public.icash_operating_budget where id=1 for update;
 perform 1 from public.icash_accounts where id=p_account for update;
 if not found then return false;end if;
 select * into c from public.icash_discovery_configs where account_id=p_account for update;
 if not found then return false;end if;
 select * into s from public.icash_bot_setups where account_id=p_account for share;
 select * into r from public.icash_operation_rates where id=p_rate for share;
 perform 1 from public.icash_market_shortlist where zip=p_zip and state ~ '^[A-Z]{2}$' for share;
 known_shortlist:=found;
 if not known_shortlist then select * into g from public.icash_property_zip_geographies where zip=p_zip for share;end if;
 checked:=clock_timestamp();
 if not c.enabled or not c.auto_enabled or c.exhausted or c.data_rights_until<=checked
 or row(c.zip,c.revision,c.next_page,c.per_page,c.rate_id,c.property_credit_micros,c.data_rights_until)
 is distinct from row(p_zip,p_revision,p_page,p_per_page,p_rate,p_unit,p_permission_until)
 or row(s.revision,s.profile->>'marketMode',s.profile->>'market') is distinct from row(p_setup_revision,p_market_mode,p_market)
 or (s.profile->>'marketMode'='city' and trim(s.profile->>'market') ~ '^[0-9]{5}$' and trim(s.profile->>'market')<>p_zip)
 or r.operation is distinct from 'property_search' or not coalesce(r.enabled,false) or r.expires_at<=checked
 or p_page<1 or p_per_page not between 1 and (case when c.research_version in (1,2) then 25 else 10 end) or p_unit<1
 or (not known_shortlist and (g.state_code is null or g.property_count is null or g.property_count<=0 or g.checked_at is null or g.checked_at>checked or g.expires_at is null or g.expires_at<=checked)) then return false;end if;
 if public.icash_stalled_research_zip(p_account,p_zip) then return false;end if;
 if not public.icash_research_zip_known(p_zip) or not public.icash_outbound_search_due(p_account) then return false;end if;
 op:='discovery:'||p_account||':'||p_revision||':'||p_page;
 select * into o from public.icash_operation_spend where operation_key=op for update;
 if found and (o.state<>'reserved' or row(o.account_id,o.rate_id,o.permission_until) is distinct from row(p_account,p_rate,p_permission_until)) then return false;end if;
 perform public.icash_reserve_operation(p_account,op,p_rate,p_permission_until,null,false);
 -- now() is the transaction start, so use wall-clock time again after any downstream wait.
 checked:=clock_timestamp();
 if c.data_rights_until<=checked or r.expires_at<=checked or (not known_shortlist and g.expires_at<=checked) then
  raise exception 'Property discovery scope expired before claim';
 end if;
 if not public.icash_claim_operation(op) then raise exception 'Property discovery claim held';end if;
 checked:=clock_timestamp();
 if c.data_rights_until<=checked or r.expires_at<=checked or (not known_shortlist and g.expires_at<=checked) then
  raise exception 'Property discovery scope expired during claim';
 end if;
 return true;
end $function$

CREATE OR REPLACE FUNCTION public.icash_reserve_research_discovery(p_account uuid, p_scope jsonb, p_plan jsonb, p_policy jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.icash_discovery_configs;ok boolean;op text;
begin
 perform 1 from public.icash_operating_budget where id=1 for update;
 perform 1 from public.icash_accounts where id=p_account for update;
 select * into c from public.icash_discovery_configs where account_id=p_account for update;
 if coalesce(c.research_version,0) not in (1,2) or p_policy is distinct from jsonb_build_object('version',case when c.research_version=2 then 'research-efficiency-v2' else 'research-efficiency-v1' end,'exclusionListId',c.research_list_id) then return false;end if;
 if c.research_list_id is not null and exists(select 1 from icash_research_private.exclusion_items where synced_at is null) then return false;end if;
 if not public.icash_research_query_ready(p_account,p_scope,p_plan,p_policy) then return false;end if;
 if p_plan is not null then
  ok:=public.icash_reserve_and_claim_filtered_discovery(p_account,p_scope->>'p_zip',(p_scope->>'p_revision')::uuid,(p_scope->>'p_page')::integer,(p_scope->>'p_per_page')::integer,(p_scope->>'p_rate')::uuid,(p_scope->>'p_unit')::bigint,(p_scope->>'p_permission_until')::timestamptz,(p_scope->>'p_setup_revision')::integer,p_scope->>'p_market_mode',p_scope->>'p_market',p_plan);
 else
  ok:=public.icash_reserve_and_claim_property_discovery(p_account,p_scope->>'p_zip',(p_scope->>'p_revision')::uuid,(p_scope->>'p_page')::integer,(p_scope->>'p_per_page')::integer,(p_scope->>'p_rate')::uuid,(p_scope->>'p_unit')::bigint,(p_scope->>'p_permission_until')::timestamptz,(p_scope->>'p_setup_revision')::integer,p_scope->>'p_market_mode',p_scope->>'p_market');
 end if;
 if not ok then return false;end if;
 op:='discovery:'||p_account||':'||(p_scope->>'p_revision')||':'||(p_scope->>'p_page');
 insert into icash_research_private.query_claims values(op,p_account,p_policy);return true;
end $function$

CREATE OR REPLACE FUNCTION public.icash_targeting_state(p_account uuid, p_revision uuid, p_page integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare c public.icash_discovery_configs;settings icash_research_private.targeting_settings;
begin
 select * into settings from icash_research_private.targeting_settings where id=1;
 if not settings.enabled then return null;end if;
 select * into c from public.icash_discovery_configs where account_id=p_account;
 if c.revision is distinct from p_revision or c.next_page is distinct from p_page then return null;end if;
 insert into public.icash_discovery_filter_cursors(account_id,revision,zip,strategy,next_page)
 select p_account,p_revision,c.zip,'target_'||e.id,1 from icash_research_private.targeting_experiments e
 where public.icash_targeting_available(p_account,c.zip,e.definition) on conflict do nothing;
 return jsonb_build_object('enabled',true,'dedupReady',public.icash_targeting_dedup_ready(p_account),'mobileVerified',settings.mobile_verified,
 'capabilities',(select result from public.icash_integration_checks where provider='dealmachine_targeting'),
 'experiments',coalesce((select jsonb_agg(jsonb_build_object('definition',e.definition,'nextPage',cur.next_page,'pages',cur.pages,'exhausted',cur.exhausted,'blocked',false))
  from icash_research_private.targeting_experiments e join public.icash_discovery_filter_cursors cur on cur.strategy='target_'||e.id
  where cur.account_id=p_account and cur.revision=p_revision and public.icash_targeting_available(p_account,c.zip,e.definition)),'[]'));
end $function$
